11		"github.com/entireio/cli/cmd/entire/cli/agent"
12		"github.com/entireio/cli/cmd/entire/cli/strategy"
13		"github.com/spf13/cobra"
14	)
15	
16	type sessionTokensReport struct {
17		SessionID       string                        `json:"session_id"`
18		Agent           string                        `json:"agent"`
19		Model           string                        `json:"model,omitempty"`
20		Status          string                        `json:"status"`
21		Source          string                        `json:"source"`
22		Tokens          *sessionTokensUsage           `json:"tokens,omitempty"`
23		Context         *sessionTokensContext         `json:"context,omitempty"`
24		Contributors    []sessionTokensContributor    `json:"contributors,omitempty"`
25		Recommendations []sessionTokensRecommendation `json:"recommendations,omitempty"`
26		Limitations     []string                      `json:"limitations,omitempty"`
27	}
28	
29	type sessionTokensUsage struct {
30		Total         int `json:"total"`
31		Input         int `json:"input"`
32		CacheRead     int `json:"cache_read"`
33		CacheWrite    int `json:"cache_write"`
34		Output        int `json:"output"`
35		APICalls      int `json:"api_calls"`
36		SubagentTotal int `json:"subagent_total,omitempty"`
37	}
38	
39	type sessionTokensContext struct {
40		Tokens     int `json:"tokens"`
41		WindowSize int `json:"window_size"`
42		Percent    int `json:"percent"`
43	}
44	
45	type sessionTokensContributor struct {
46		Kind       string   `json:"kind"`
47		Label      string   `json:"label"`
48		Tokens     int      `json:"tokens,omitempty"`
49		Percent    int      `json:"percent,omitempty"`
50		Confidence string   `json:"confidence"`
51		Signals    []string `json:"signals,omitempty"`
52	}
53	
54	type sessionTokensRecommendation struct {
55		ID       string   `json:"id"`
56		Severity string   `json:"severity"`
57		Message  string   `json:"message"`
58		Signals  []string `json:"signals,omitempty"`
59	}
60	
61	type tokenRecommendationSignals struct {
62		Tokens          *sessionTokensUsage
63		Context         *sessionTokensContext
64		TurnCount       int
65		CheckpointCount int
66	}
67	
68	func newTokensCmd() *cobra.Command {
69		var jsonFlag bool
70		var currentFlag bool
71		var agentBriefFlag bool
72	
73		cmd := &cobra.Command{
74			Use:   "tokens [session-id]",
75			Short: "Show token usage and optimization recommendations for a session",
76			Long: `Show token usage and optimization recommendations for a session.
77	
78	When no session ID is provided, Entire reports on the most recently active
79	session for the current worktree. The report is local and deterministic: it uses
80	token and context data Entire already captured for the session.
81	
82	Use --agent-brief when an agent needs compact guidance for the next step, for
83	example: "Use Entire token tracking to check how this session is doing and
84	optimize next steps."`,
85			Args: cobra.MaximumNArgs(1),
86			RunE: func(cmd *cobra.Command, args []string) error {
87				if jsonFlag && agentBriefFlag {
88					return errors.New("--json and --agent-brief are mutually exclusive")
89				}
90				if currentFlag && len(args) > 0 {
91					return errors.New("--current and session ID argument are mutually exclusive")
92				}
93	
94				sessionID := ""
95				if len(args) > 0 {
96					sessionID = args[0]
97				}
98				return runSessionTokens(cmd.Context(), cmd, sessionID, currentFlag, jsonFlag, agentBriefFlag)
99			},
100		}
101	
102		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
103		cmd.Flags().BoolVar(&currentFlag, "current", false, "Use the current worktree's most recent session")
104		cmd.Flags().BoolVar(&agentBriefFlag, "agent-brief", false, "Output compact next-step guidance for agents")
105		return cmd
106	}
107	
108	func runSessionTokens(ctx context.Context, cmd *cobra.Command, sessionID string, current, jsonOutput, agentBrief bool) error {
109		if sessionID == "" || current {
110			sessionID = strategy.FindMostRecentSession(ctx)
111			if sessionID == "" {
112				fmt.Fprintln(cmd.OutOrStdout(), "No active session found in this worktree.")
113				return nil
114			}
115		}
116	
117		state, err := strategy.LoadSessionState(ctx, sessionID)
118		if err != nil {
119			return fmt.Errorf("failed to load session: %w", err)
120		}
121		if state == nil {
122			cmd.SilenceUsage = true
123			fmt.Fprintln(cmd.ErrOrStderr(), "Session not found.")
124			return NewSilentError(fmt.Errorf("session not found: %s", sessionID))
125		}
126	
127		report := buildSessionTokensReport(state, sessionPhaseLabel(state))
128		if jsonOutput {
129			return writeSessionTokensJSON(cmd.OutOrStdout(), report)
130		}
131		if agentBrief {
132			writeSessionTokensAgentBrief(cmd.OutOrStdout(), report)
133			return nil
134		}
135		writeSessionTokensText(cmd.OutOrStdout(), report)
136		return nil
137	}
138	
139	func buildSessionTokensReport(state *strategy.SessionState, status string) sessionTokensReport {
140		agentLabel := string(state.AgentType)
141		if agentLabel == "" {
142			agentLabel = unknownPlaceholder
143		}
144	
145		report := sessionTokensReport{
146			SessionID: state.SessionID,
147			Agent:     agentLabel,
148			Model:     state.ModelName,
149			Status:    status,
150			Source:    "session_state",
151		}
152	
153		if tokens := buildSessionTokensUsage(state.TokenUsage); tokens != nil {
154			report.Tokens = tokens
155			if tokens.SubagentTotal > 0 {
156				report.Contributors = append(report.Contributors, sessionTokensContributor{
157					Kind:       "subagents",
158					Label:      "Subagents",
159					Tokens:     tokens.SubagentTotal,
160					Confidence: "reported",
161					Signals:    []string{"subagent_tokens"},
162				})
163			}
164		} else {
165			report.Limitations = append(report.Limitations, "No token usage recorded for this session.")
166			report.Recommendations = append(report.Recommendations, sessionTokensRecommendation{
167				ID:       "no-token-data",
168				Severity: "low",
169				Message:  "Token usage is unavailable for this session; the agent may not expose token data yet, or no checkpoint has captured it.",
170				Signals:  []string{"missing_token_usage"},
171			})
172		}
173	
174		if contextInfo := buildSessionTokensContext(state.ContextTokens, state.ContextWindowSize); contextInfo != nil {
175			report.Context = contextInfo
176			report.Contributors = append(report.Contributors, sessionTokensContributor{
177				Kind:       "context_pressure",
178				Label:      "Context pressure",
179				Percent:    contextInfo.Percent,
180				Confidence: "reported",
181				Signals:    []string{"context_tokens"},
182			})
183		}
184	
185		if labels := skillEventLabels(state.SkillEvents); len(labels) > 0 {
186			report.Contributors = append(report.Contributors, sessionTokensContributor{
187				Kind:       "skills",
188				Label:      "Skills/slash commands: " + strings.Join(labels, ", "),
189				Confidence: "reported",
190				Signals:    []string{"skill_events"},
191			})
192		}
193	
194		report.Recommendations = append(report.Recommendations, recommendationRules(tokenRecommendationSignals{
195			Tokens:          report.Tokens,
196			Context:         report.Context,
197			TurnCount:       state.SessionTurnCount,
198			CheckpointCount: state.StepCount,
199		})...)
200		return report
201	}
202	
203	func buildSessionTokensUsage(usage *agent.TokenUsage) *sessionTokensUsage {
204		total := totalTokens(usage)
205		if total == 0 {
206			return nil
207		}
208		return &sessionTokensUsage{
209			Total:         total,
210			Input:         usage.InputTokens,
211			CacheRead:     usage.CacheReadTokens,
212			CacheWrite:    usage.CacheCreationTokens,
213			Output:        usage.OutputTokens,
214			APICalls:      usage.APICallCount,
215			SubagentTotal: totalTokens(usage.SubagentTokens),
216		}
217	}
218	
219	func buildSessionTokensContext(tokens, windowSize int) *sessionTokensContext {
220		if tokens <= 0 || windowSize <= 0 {
221			return nil
222		}
223		return &sessionTokensContext{
224			Tokens:     tokens,
225			WindowSize: windowSize,
226			Percent:    roundedPercent(tokens, windowSize),
227		}
228	}
229	
230	func roundedPercent(value, total int) int {
231		if total <= 0 {
232			return 0
233		}
234		return (value*100 + total/2) / total
235	}
236	
237	func recommendationRules(signals tokenRecommendationSignals) []sessionTokensRecommendation {
238		var recs []sessionTokensRecommendation
239	
240		cacheReadHotspot := false
241		if signals.Tokens != nil && signals.Tokens.Total > 0 && signals.Tokens.CacheRead > 0 {
242			cacheReadPercent := tokenPercent(signals.Tokens.CacheRead, signals.Tokens.Total)
243			if cacheReadPercent >= 80 {
244				cacheReadHotspot = true
245				recs = append(recs, sessionTokensRecommendation{
246					ID:       "context-replay-hotspot",
247					Severity: "high",
248					Message: fmt.Sprintf(
249						"Cache/context replay is %s of token volume; reduce unnecessary follow-up calls in this large-context session.",
250						formatPercent(cacheReadPercent),
251					),
252					Signals: []string{"cache_read_tokens"},
253				})
254			}
255		}
256		if signals.Tokens != nil && signals.Tokens.APICalls >= 20 {
257			message := fmt.Sprintf("API call count is high for one session: %d calls. Batch the next diagnosis and reduce iterative calls.", signals.Tokens.APICalls)
258			if cacheReadHotspot {
259				message = fmt.Sprintf("Large context was replayed across %d API calls; batch the next diagnosis and reduce iterative tool calls.", signals.Tokens.APICalls)
260			}
261			recs = append(recs, sessionTokensRecommendation{
262				ID:       "api-call-amplification",
263				Severity: "medium",
264				Message:  message,
265				Signals:  []string{"api_call_count"},
266			})
267		}
268		if signals.Tokens != nil && signals.Tokens.SubagentTotal > 0 && signals.Tokens.SubagentTotal*100 >= signals.Tokens.Total*10 {
269			recs = append(recs, sessionTokensRecommendation{
270				ID:       "subagent-heavy",
271				Severity: "medium",
272				Message:  "Scope subagent tasks tightly; give each subagent a narrow objective and expected output.",
273				Signals:  []string{"subagent_tokens"},
274			})
275		}
276		if signals.Context != nil && signals.Context.Percent >= 80 {
277			recs = append(recs, sessionTokensRecommendation{
278				ID:       "high-context-pressure",
279				Severity: "medium",
280				Message:  fmt.Sprintf("Context pressure is %d%% of the window; preserve only relevant context before continuing.", signals.Context.Percent),
281				Signals:  []string{"context_tokens"},
282			})
283		}
284		if cacheReadHotspot && signals.Tokens != nil && signals.Tokens.APICalls >= 20 {
285			recs = append(recs, sessionTokensRecommendation{
286				ID:       "summarize-before-boundary",
287				Severity: "low",
288				Message:  "Compact or restart after summarizing this investigation; do not discard useful findings just because cache read is high.",
289				Signals:  []string{"cache_read_tokens", "api_call_count"},
290			})
291		}
292		if signals.TurnCount >= 10 || signals.CheckpointCount >= 5 {
293			recs = append(recs, sessionTokensRecommendation{
294				ID:       "long-session",
295				Severity: "low",
296				Message:  "Compact or restart after summarizing the useful findings if older context is no longer needed.",
297				Signals:  []string{"turn_count", "checkpoint_count"},
298			})
299		}
300	
301		return recs
302	}
303	
304	func tokenPercent(value, total int) float64 {
305		if total <= 0 {
306			return 0
307		}
308		return float64(value) * 100 / float64(total)
309	}
310	
311	func formatPercent(percent float64) string {
312		formatted := fmt.Sprintf("%.1f", percent)
313		formatted = strings.TrimSuffix(formatted, ".0")
314		return formatted + "%"
315	}
316	
317	func skillEventLabels(events []agent.SkillEvent) []string {
318		seen := make(map[string]struct{}, len(events))
319		labels := make([]string, 0, len(events))
320		for _, event := range events {
321			label := event.Collapse.Label
322			if label == "" && event.Native != nil {
323				label = event.Native["command"]
324			}
325			if label == "" {
326				label = event.Skill.Name
327			}
328			if label == "" {
329				continue
330			}
331			if _, ok := seen[label]; ok {
332				continue
333			}
334			seen[label] = struct{}{}
335			labels = append(labels, label)
336		}
337		return labels
338	}
339	
340	func writeSessionTokensJSON(w io.Writer, report sessionTokensReport) error {
341		enc := json.NewEncoder(w)
342		enc.SetIndent("", "  ")
343		if err := enc.Encode(report); err != nil {
344			return fmt.Errorf("failed to encode session token report: %w", err)
345		}
346		return nil
347	}
348	
349	func writeSessionTokensText(w io.Writer, report sessionTokensReport) {
350		fmt.Fprintln(w, "Session tokens")
351		fmt.Fprintln(w)
352		fmt.Fprintf(w, "Session: %s\n", report.SessionID)
353		fmt.Fprintf(w, "Agent:   %s\n", report.Agent)
354		if report.Model != "" {
355			fmt.Fprintf(w, "Model:   %s\n", report.Model)
356		}
357		fmt.Fprintf(w, "Status:  %s\n", report.Status)
358	
359		writeTokenUsageSection(w, report.Tokens)
360		if len(report.Recommendations) > 0 {
361			writeTokenRecommendations(w, report.Recommendations)
362		}
363	
364		writeTokenContributors(w, report.Contributors, report.Context)
365		writeTokenLimitations(w, report.Limitations)
366	}
367	
368	func writeSessionTokensAgentBrief(w io.Writer, report sessionTokensReport) {
369		fmt.Fprintln(w, "Session token brief")
370		fmt.Fprintf(w, "Session: %s\n", report.SessionID)
371		fmt.Fprintln(w)
372		fmt.Fprintln(w, agentBriefUsageLine(report.Tokens))
373		fmt.Fprintln(w)
374		fmt.Fprintln(w, "Next best action:")
375		fmt.Fprintln(w, agentBriefNextAction(report))
376	
377		signals := agentBriefSignals(report)
378		if len(signals) > 0 {
379			fmt.Fprintln(w)
380			fmt.Fprintln(w, "Signals:")
381			for _, signal := range signals {
382				fmt.Fprintf(w, "- %s\n", signal)
383			}
384		}
385	}
386	
387	func agentBriefUsageLine(tokens *sessionTokensUsage) string {
388		if tokens == nil {
389			return "Token usage: unavailable."
390		}
391		if tokens.CacheRead > 0 {
392			return fmt.Sprintf(
393				"Token usage: %s total; %s cache/context replay; %s.",
394				formatTokenCount(tokens.Total),
395				formatPercent(tokenPercent(tokens.CacheRead, tokens.Total)),
396				formatAPICalls(tokens.APICalls),
397			)
398		}
399		return fmt.Sprintf("Token usage: %s total; %s.", formatTokenCount(tokens.Total), formatAPICalls(tokens.APICalls))
400	}
401	
402	func formatAPICalls(count int) string {
403		if count == 1 {
404			return "1 API call"
405		}
406		return fmt.Sprintf("%d API calls", count)
407	}
408	
409	func agentBriefNextAction(report sessionTokensReport) string {
410		switch {
411		case hasTokenRecommendation(report, "context-replay-hotspot") && hasTokenRecommendation(report, "api-call-amplification"):
412			return "Summarize the useful findings, then batch the next diagnostic step. Avoid more exploratory reads until you have a narrowed hypothesis."
413		case hasTokenRecommendation(report, "context-replay-hotspot"):
414			return "Summarize the current useful findings before continuing, and keep the next prompt narrow."
415		case hasTokenRecommendation(report, "no-token-data"):
416			return "Token usage is not available yet. Use this as a context check, not a spend diagnosis; continue after the next checkpoint captures usage."
417		case hasTokenRecommendation(report, "subagent-heavy"):
418			return "Keep the next agent or subagent task narrow with a concrete expected output; avoid broad parallel exploration."
419		case hasTokenRecommendation(report, "high-context-pressure"):
420			return "Preserve the useful findings and compact or restart before adding more broad context."
421		case hasTokenRecommendation(report, "long-session"):
422			return "Compact or restart after summarizing useful findings if older context is no longer needed."
423		default:
424			return "Continue normally; no high-signal token optimization is available from this session yet."
425		}
426	}
427	
428	func agentBriefSignals(report sessionTokensReport) []string {
429		var signals []string
430		if hasTokenRecommendation(report, "context-replay-hotspot") {
431			signals = append(signals, "Cache/context replay dominates token volume.")
432		}
433		if hasTokenRecommendation(report, "api-call-amplification") {
434			signals = append(signals, "API call count is high for one session.")
435		}
436		if hasTokenRecommendation(report, "subagent-heavy") {
437			signals = append(signals, "Subagent usage is a meaningful part of total tokens.")
438		}
439		if hasTokenRecommendation(report, "high-context-pressure") {
440			signals = append(signals, "Context pressure is high.")
441		}
442		if hasTokenRecommendation(report, "long-session") {
443			signals = append(signals, "Session has crossed a long-session or checkpoint boundary.")
444		}
445		if hasTokenRecommendation(report, "no-token-data") {
446			signals = append([]string{"Token usage is unavailable for this session."}, signals...)
447		}
448		if len(signals) == 0 && report.Tokens != nil {
449			signals = append(signals, "No high-signal token risk detected from captured usage.")
450		}
451		return signals
452	}
453	
454	func hasTokenRecommendation(report sessionTokensReport, id string) bool {
455		for _, rec := range report.Recommendations {
456			if rec.ID == id {
457				return true
458			}
459		}
460		return false
461	}
462	
463	func writeTokenRecommendations(w io.Writer, recs []sessionTokensRecommendation) {
464		fmt.Fprintln(w)
465		fmt.Fprintln(w, "Recommendations")
466		for _, rec := range recs {
467			fmt.Fprintf(w, "- %s\n", rec.Message)
468		}
469	}
470	
471	func writeTokenUsageSection(w io.Writer, tokens *sessionTokensUsage) {
