15	)
16	
17	type checkpointTokensReport struct {
18		CheckpointID    string                        `json:"checkpoint_id"`
19		SessionCount    int                           `json:"session_count"`
20		SessionID       string                        `json:"session_id,omitempty"`
21		Agent           string                        `json:"agent,omitempty"`
22		Agents          []string                      `json:"agents,omitempty"`
23		Model           string                        `json:"model,omitempty"`
24		Models          []string                      `json:"models,omitempty"`
25		Branch          string                        `json:"branch,omitempty"`
26		Source          string                        `json:"source"`
27		Tokens          *sessionTokensUsage           `json:"tokens,omitempty"`
28		Context         *sessionTokensContext         `json:"context,omitempty"`
29		Contributors    []sessionTokensContributor    `json:"contributors,omitempty"`
30		Recommendations []sessionTokensRecommendation `json:"recommendations,omitempty"`
31		Comparison      *checkpointTokensComparison   `json:"comparison,omitempty"`
32		Limitations     []string                      `json:"limitations,omitempty"`
33	}
34	
35	type checkpointTokensComparison struct {
36		BaselineCheckpointID string                       `json:"baseline_checkpoint_id"`
37		TargetCheckpointID   string                       `json:"target_checkpoint_id"`
38		Status               string                       `json:"status"`
39		Total                *checkpointTokensMetricDelta `json:"total,omitempty"`
40		CacheRead            *checkpointTokensMetricDelta `json:"cache_read,omitempty"`
41		APICalls             *checkpointTokensMetricDelta `json:"api_calls,omitempty"`
42		Qualification        string                       `json:"qualification"`
43		Limitations          []string                     `json:"limitations,omitempty"`
44	}
45	
46	type checkpointTokensMetricDelta struct {
47		Baseline      int      `json:"baseline"`
48		Current       int      `json:"current"`
49		Change        int      `json:"change"`
50		ChangePercent *float64 `json:"change_percent,omitempty"`
51		Direction     string   `json:"direction"`
52	}
53	
54	const (
55		checkpointComparisonStatusUnavailable       = "unavailable"
56		checkpointComparisonStatusObservedReduction = "observed_reduction"
57		checkpointComparisonStatusObservedIncrease  = "observed_increase"
58		checkpointComparisonStatusObservedNoChange  = "observed_no_change"
59	)
60	
61	func newCheckpointTokensCmd() *cobra.Command {
62		var jsonFlag bool
63		var compareFlag string
64	
65		cmd := &cobra.Command{
66			Use:   "tokens <checkpoint-id>",
67			Short: "Show token usage and optimization recommendations for a checkpoint",
68			Long: `Show token usage and optimization recommendations for a checkpoint.
69	
70	The report reads committed checkpoint metadata and is local and deterministic.
71	Checkpoint IDs may be abbreviated as long as the prefix is unambiguous.
72	
73	Use --compare <checkpoint-id> to compare this checkpoint against a previous
74	checkpoint and qualify observed token reduction or increase.`,
75			Args: cobra.ExactArgs(1),
76			RunE: func(cmd *cobra.Command, args []string) error {
77				return runCheckpointTokens(cmd.Context(), cmd, args[0], jsonFlag, compareFlag)
78			},
79		}
80	
81		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
82		cmd.Flags().StringVar(&compareFlag, "compare", "", "Compare against a baseline checkpoint ID")
83		return cmd
84	}
85	
86	func runCheckpointTokens(ctx context.Context, cmd *cobra.Command, checkpointIDPrefix string, jsonOutput bool, comparePrefix string) error {
87		report, lookup, err := loadCheckpointTokensReport(ctx, cmd, checkpointIDPrefix)
88		if lookup != nil {
89			defer lookup.Close()
90		}
91		if err != nil {
92			return err
93		}
94	
95		if comparePrefix != "" {
96			baselineReport, baselineLookup, err := loadCheckpointTokensReport(ctx, cmd, comparePrefix)
97			if baselineLookup != nil {
98				defer baselineLookup.Close()
99			}
100			if err != nil {
101				return err
102			}
103			report.Comparison = buildCheckpointTokensComparison(report, baselineReport)
104		}
105	
106		if jsonOutput {
107			return writeCheckpointTokensJSON(cmd.OutOrStdout(), report)
108		}
109		writeCheckpointTokensText(cmd.OutOrStdout(), report)
110		return nil
111	}
112	
113	func loadCheckpointTokensReport(ctx context.Context, cmd *cobra.Command, checkpointIDPrefix string) (checkpointTokensReport, *explainCheckpointLookup, error) {
114		cpID, lookup, err := resolveExplainCheckpointID(ctx, cmd.ErrOrStderr(), explainExportOptions{target: checkpointIDPrefix})
115		if err != nil {
116			return checkpointTokensReport{}, lookup, err
117		}
118	
119		summary, err := lookup.store.ReadCommitted(ctx, cpID)
120		if err != nil {
121			return checkpointTokensReport{}, lookup, fmt.Errorf("failed to read checkpoint: %w", err)
122		}
123		if summary == nil || len(summary.Sessions) == 0 {
124			cmd.SilenceUsage = true
125			fmt.Fprintln(cmd.ErrOrStderr(), "Checkpoint not found.")
126			return checkpointTokensReport{}, lookup, NewSilentError(fmt.Errorf("%w: %s", checkpoint.ErrCheckpointNotFound, checkpointIDPrefix))
127		}
128	
129		metas := make([]*checkpoint.CommittedMetadata, 0, len(summary.Sessions))
130		for i := range len(summary.Sessions) {
131			meta, err := lookup.store.ReadSessionMetadata(ctx, cpID, i)
132			if err != nil {
133				return checkpointTokensReport{}, lookup, fmt.Errorf("failed to read checkpoint session %d metadata: %w", i, err)
134			}
135			metas = append(metas, meta)
136		}
137	
138		return buildCheckpointTokensReport(cpID, summary, metas), lookup, nil
139	}
140	
141	func buildCheckpointTokensReport(cpID id.CheckpointID, summary *checkpoint.CheckpointSummary, metas []*checkpoint.CommittedMetadata) checkpointTokensReport {
142		report := checkpointTokensReport{
143			CheckpointID: cpID.String(),
144			Source:       "committed_checkpoint",
145		}
146		if summary != nil {
147			report.Branch = summary.Branch
148			report.SessionCount = len(summary.Sessions)
149		}
150		if report.SessionCount == 0 {
151			report.SessionCount = len(metas)
152		}
153		report.Agents = checkpointAgentLabels(metas)
154		report.Models = checkpointModelLabels(metas)
155	
156		if len(metas) == 1 && metas[0] != nil {
157			meta := metas[0]
158			report.SessionID = meta.SessionID
159			if len(report.Agents) > 0 {
160				report.Agent = report.Agents[0]
161			}
162			if len(report.Models) > 0 {
163				report.Model = report.Models[0]
164			}
165			if report.Branch == "" {
166				report.Branch = meta.Branch
167			}
168		} else if len(metas) > 1 && report.Branch == "" {
169			report.Branch = firstCheckpointBranch(metas)
170		}
171	
172		usage := aggregateCheckpointTokenUsage(metas)
173		if usage == nil && summary != nil {
174			usage = summary.TokenUsage
175		}
176		if tokens := buildSessionTokensUsage(usage); tokens != nil {
177			report.Tokens = tokens
178			if tokens.SubagentTotal > 0 {
179				report.Contributors = append(report.Contributors, sessionTokensContributor{
180					Kind:       "subagents",
181					Label:      "Subagents",
182					Tokens:     tokens.SubagentTotal,
183					Confidence: "reported",
184					Signals:    []string{"subagent_tokens"},
185				})
186			}
187		} else {
188			report.Limitations = append(report.Limitations, "No token usage recorded for this checkpoint.")
189			report.Recommendations = append(report.Recommendations, sessionTokensRecommendation{
190				ID:       "no-token-data",
191				Severity: "low",
192				Message:  "Token usage is unavailable for this checkpoint; the agent may not expose token data yet, or this checkpoint predates token tracking.",
193				Signals:  []string{"missing_token_usage"},
194			})
195		}
196	
197		var turnCount int
198		var skillEvents []agent.SkillEvent
199		if len(metas) == 1 && metas[0] != nil {
200			meta := metas[0]
201			if metrics := meta.SessionMetrics; metrics != nil {
202				turnCount = metrics.TurnCount
203				if contextInfo := buildSessionTokensContext(metrics.ContextTokens, metrics.ContextWindowSize); contextInfo != nil {
204					report.Context = contextInfo
205					report.Contributors = append(report.Contributors, sessionTokensContributor{
206						Kind:       "context_pressure",
207						Label:      "Context pressure",
208						Percent:    contextInfo.Percent,
209						Confidence: "reported",
210						Signals:    []string{"context_tokens"},
211					})
212				}
213			}
214			skillEvents = meta.SkillEvents
215		} else {
216			for _, meta := range metas {
217				if meta == nil {
218					continue
219				}
220				if metrics := meta.SessionMetrics; metrics != nil {
221					turnCount += metrics.TurnCount
222				}
223				skillEvents = append(skillEvents, meta.SkillEvents...)
224			}
225		}
226		if labels := skillEventLabels(skillEvents); len(labels) > 0 {
227			report.Contributors = append(report.Contributors, sessionTokensContributor{
228				Kind:       "skills",
229				Label:      "Skills/slash commands: " + strings.Join(labels, ", "),
230				Confidence: "reported",
231				Signals:    []string{"skill_events"},
232			})
233		}
234	
235		var checkpointCount int
236		if summary != nil {
237			checkpointCount = summary.CheckpointsCount
238		}
239		report.Recommendations = append(report.Recommendations, recommendationRules(tokenRecommendationSignals{
240			Tokens:          report.Tokens,
241			Context:         report.Context,
242			TurnCount:       turnCount,
243			CheckpointCount: checkpointCount,
244		})...)
245		return report
246	}
