248	func checkpointAgentLabels(metas []*checkpoint.CommittedMetadata) []string {
249		labels := make([]string, 0, len(metas))
250		seen := make(map[string]struct{}, len(metas))
251		for _, meta := range metas {
252			label := unknownPlaceholder
253			if meta != nil && meta.Agent != "" {
254				label = string(meta.Agent)
255			}
256			if _, ok := seen[label]; ok {
257				continue
258			}
259			seen[label] = struct{}{}
260			labels = append(labels, label)
261		}
262		return labels
263	}
264	
265	func checkpointModelLabels(metas []*checkpoint.CommittedMetadata) []string {
266		labels := make([]string, 0, len(metas))
267		seen := make(map[string]struct{}, len(metas))
268		for _, meta := range metas {
269			if meta == nil || meta.Model == "" {
270				continue
271			}
272			if _, ok := seen[meta.Model]; ok {
273				continue
274			}
275			seen[meta.Model] = struct{}{}
276			labels = append(labels, meta.Model)
277		}
278		return labels
