48	func newTokensGroupCmd() *cobra.Command {
49		cmd := &cobra.Command{
50			Use:   "tokens",
51			Short: "Analyze token usage across sessions and checkpoints",
52			Long: `Analyze token usage across sessions and checkpoints.
53	
54	Commands:
55	  profile  Aggregate token usage across committed checkpoints
56	
57	Examples:
58	  entire tokens profile
59	  entire tokens profile --json`,
60			RunE: func(cmd *cobra.Command, _ []string) error {
61				return cmd.Help()
62			},
63		}
