69	func newTokensProfileCmd() *cobra.Command {
70		var jsonFlag bool
71		var limitFlag int
72		var allFlag bool
73	
74		cmd := &cobra.Command{
75			Use:   "profile",
76			Short: "Aggregate token usage and recommendations across checkpoint history",
77			Long: `Aggregate token usage and recommendations across committed checkpoint history.
78	
79	The profile reads committed checkpoint metadata only. It does not inspect
80	transcripts or source files, so it is deterministic and avoids adding token
81	cost while diagnosing token usage. By default it scans the latest 50 committed
82	checkpoints; use --limit or --all to change the scope.`,
83			Args: cobra.NoArgs,
84			RunE: func(cmd *cobra.Command, _ []string) error {
85				limit := limitFlag
86				if allFlag {
87					limit = 0
88				} else if limit <= 0 {
89					return errors.New("--limit must be positive unless --all is used")
90				}
91				return runTokensProfile(cmd.Context(), cmd, jsonFlag, limit)
92			},
93		}
94	
95		cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output as JSON")
96		cmd.Flags().IntVar(&limitFlag, "limit", 50, "Maximum committed checkpoints to analyze")
97		cmd.Flags().BoolVar(&allFlag, "all", false, "Analyze all committed checkpoints")
98		return cmd
99	}
100	
101	func runTokensProfile(ctx context.Context, cmd *cobra.Command, jsonOutput bool, limit int) error {
102		repo, err := openRepository(ctx)
103		if err != nil {
104			cmd.SilenceUsage = true
105			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository.")
106			return NewSilentError(err)
107		}
108		defer repo.Close()
109	
110		store := checkpoint.NewCommittedReadStore(ctx, repo)
111		infos, err := store.ListCommitted(ctx)
112		if err != nil {
113			return fmt.Errorf("failed to list checkpoints: %w", err)
114		}
115	
116		report, err := buildTokensProfileReport(ctx, store, infos, limit)
117		if err != nil {
118			return err
119		}
120	
121		if jsonOutput {
122			return writeTokensProfileJSON(cmd.OutOrStdout(), report)
123		}
124		writeTokensProfileText(cmd.OutOrStdout(), report)
125		return nil
126	}
127	
128	func buildTokensProfileReport(ctx context.Context, store *checkpoint.GitStore, infos []checkpoint.CommittedInfo, limit int) (tokensProfileReport, error) {
129		checkpointsAvailable := len(infos)
130		infos = limitTokensProfileCheckpoints(infos, limit)
131		report := tokensProfileReport{
132			Source:               "committed_checkpoints",
133			CheckpointsAvailable: checkpointsAvailable,
134			CheckpointsAnalyzed:  len(infos),
135		}
136		signals := make(map[string]*tokensProfileSignal, len(tokensProfileSignalDefinitions))
137		var aggregate *agent.TokenUsage
138	
139		for _, info := range infos {
140			if err := ctx.Err(); err != nil {
141				return tokensProfileReport{}, err //nolint:wrapcheck // Propagating context cancellation.
142			}
143	
144			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
145			if err != nil {
146				return tokensProfileReport{}, fmt.Errorf("failed to read checkpoint %s: %w", info.CheckpointID, err)
147			}
148			if summary == nil {
149				report.MissingTokenData++
150				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
151				continue
152			}
153	
154			usage, metadataReadWarning, err := tokensProfileCheckpointUsage(ctx, store, info.CheckpointID, summary)
155			if err != nil {
156				return tokensProfileReport{}, err
157			}
158			if metadataReadWarning {
159				report.MetadataReadWarnings++
160			}
161			tokens := buildSessionTokensUsage(usage)
162			if tokens == nil {
163				report.MissingTokenData++
164				addTokensProfileSignal(signals, "missing-token-data", info.CheckpointID, report.CheckpointsAnalyzed)
165				continue
166			}
167	
168			report.CheckpointsWithTokenData++
169			aggregate = addCheckpointTokenUsage(aggregate, usage)
170			addTokensProfileTokenSignals(signals, info.CheckpointID, tokens, report.CheckpointsAnalyzed)
171		}
172	
173		report.Tokens = buildSessionTokensUsage(aggregate)
174		report.Signals = orderedTokensProfileSignals(signals)
175		report.Recommendations = tokensProfileRecommendations(report)
176		report.Limitations = tokensProfileLimitations(report)
177		return report, nil
178	}
179	
180	func limitTokensProfileCheckpoints(infos []checkpoint.CommittedInfo, limit int) []checkpoint.CommittedInfo {
181		if limit <= 0 || len(infos) <= limit {
182			return infos
183		}
184		return infos[:limit]
185	}
