187	func tokensProfileCheckpointUsage(ctx context.Context, store *checkpoint.GitStore, checkpointID id.CheckpointID, summary *checkpoint.CheckpointSummary) (*agent.TokenUsage, bool, error) {
188		if summary == nil {
189			return nil, false, nil
190		}
191	
192		metas := make([]*checkpoint.CommittedMetadata, 0, len(summary.Sessions))
193		metadataReadWarning := false
194		for i := range len(summary.Sessions) {
195			meta, err := store.ReadSessionMetadata(ctx, checkpointID, i)
196			if err != nil {
197				if ctxErr := ctx.Err(); ctxErr != nil {
198					return nil, false, ctxErr //nolint:wrapcheck // Propagating context cancellation.
199				}
200				metadataReadWarning = true
201				continue
202			}
203			metas = append(metas, meta)
204		}
205		sessionUsage := aggregateCheckpointTokenUsage(metas)
206		if !metadataReadWarning && sessionUsage != nil {
207			return sessionUsage, false, nil
208		}
209		if summary.TokenUsage != nil {
210			return summary.TokenUsage, metadataReadWarning, nil
211		}
212		return sessionUsage, metadataReadWarning, nil
213	}
214	
215	func addTokensProfileTokenSignals(signals map[string]*tokensProfileSignal, checkpointID id.CheckpointID, tokens *sessionTokensUsage, denominator int) {
216		if tokens == nil {
217			return
218		}
219		if tokens.Total > 0 && tokenPercent(tokens.CacheRead, tokens.Total) >= 80 {
220			addTokensProfileSignal(signals, "context-replay-hotspot", checkpointID, denominator)
221		}
222		if tokens.APICalls >= 20 {
223			addTokensProfileSignal(signals, "api-call-amplification", checkpointID, denominator)
224		}
225		if tokens.Total > 0 && tokens.SubagentTotal*100 >= tokens.Total*10 {
226			addTokensProfileSignal(signals, "subagent-heavy", checkpointID, denominator)
227		}
228	}
229	
230	func addTokensProfileSignal(signals map[string]*tokensProfileSignal, signalID string, checkpointID id.CheckpointID, denominator int) {
231		signal := signals[signalID]
232		if signal == nil {
233			definition := tokensProfileSignalDefinitionFor(signalID)
234			signal = &tokensProfileSignal{
235				ID:    definition.id,
236				Label: definition.label,
237			}
238			signals[signalID] = signal
239		}
240		signal.Count++
241		if denominator > 0 {
242			signal.Percent = roundedPercent(signal.Count, denominator)
243		}
244		if checkpointID != "" {
245			signal.CheckpointIDs = append(signal.CheckpointIDs, checkpointID.String())
246		}
247	}
