249	func tokensProfileSignalDefinitionFor(signalID string) tokensProfileSignalDefinition {
250		for _, definition := range tokensProfileSignalDefinitions {
251			if definition.id == signalID {
252				return definition
253			}
254		}
255		return tokensProfileSignalDefinition{id: signalID, label: signalID}
256	}
