258	func orderedTokensProfileSignals(signals map[string]*tokensProfileSignal) []tokensProfileSignal {
259		ordered := make([]tokensProfileSignal, 0, len(signals))
260		for _, definition := range tokensProfileSignalDefinitions {
261			if signal := signals[definition.id]; signal != nil {
262				ordered = append(ordered, *signal)
263			}
264		}
265		return ordered
266	}
