279	
280		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 ||
281			tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
282			recs = append(recs, sessionTokensRecommendation{
