284				Severity: "high",
285				Message:  "Use `entire search` for prior decisions/checkpoints before broad re-investigation.",
286				Signals:  []string{"cache_read_tokens", "api_call_count"},
287			})
288		}
289		if tokensProfileSignalCount(report.Signals, "api-call-amplification") > 0 {
290			recs = append(recs, sessionTokensRecommendation{
291				ID:       "batch-diagnostics",
292				Severity: "medium",
293				Message:  "Batch diagnostic reads around one narrowed hypothesis when API call amplification repeats.",
294				Signals:  []string{"api_call_count"},
295			})
296		}
297		if tokensProfileSignalCount(report.Signals, "context-replay-hotspot") > 0 {
298			recs = append(recs, sessionTokensRecommendation{
299				ID:       "preserve-then-compact",
300				Severity: "medium",
301				Message:  "Summarize useful findings before continuing large-context work; compact or restart only after preserving relevant context.",
302				Signals:  []string{"cache_read_tokens"},
303			})
304		}
305		if tokensProfileSignalCount(report.Signals, "subagent-heavy") > 0 {
306			recs = append(recs, sessionTokensRecommendation{
307				ID:       "scope-subagents",
308				Severity: "medium",
309				Message:  "Scope subagent tasks tightly with a narrow objective and expected output.",
310				Signals:  []string{"subagent_tokens"},
311			})
312		}
313		if report.MissingTokenData > 0 {
314			recs = append(recs, sessionTokensRecommendation{
315				ID:       "improve-token-coverage",
316				Severity: "low",
317				Message:  "Increase token coverage by using agents and checkpoints that report token usage.",
318				Signals:  []string{"missing_token_usage"},
319			})
320		}
321	
322		if len(recs) == 0 {
323			recs = append(recs, sessionTokensRecommendation{
324				ID:       "no-repeated-hotspots",
325				Severity: "low",
326				Message:  "No repeated token hotspots were visible in committed checkpoint metadata.",
327				Signals:  []string{"checkpoint_token_metadata"},
328			})
329		}
330		return recs
331	}
