342	func tokensProfileLimitations(report tokensProfileReport) []string {
343		var limitations []string
344		if report.CheckpointsAvailable > report.CheckpointsAnalyzed {
345			limitations = append(limitations, fmt.Sprintf("Limited to latest %d of %d committed checkpoints; use --limit or --all to change scope.", report.CheckpointsAnalyzed, report.CheckpointsAvailable))
346		}
347		if report.CheckpointsAnalyzed == 0 {
348			limitations = append(limitations, "No committed checkpoints found.")
349		}
350		if report.MissingTokenData > 0 {
351			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s did not include token usage.", report.MissingTokenData, pluralSuffix(report.MissingTokenData)))
352		}
353		if report.MetadataReadWarnings > 0 {
354			limitations = append(limitations, fmt.Sprintf("%d checkpoint%s had incomplete session metadata; profile used root token summaries or readable sessions where available.", report.MetadataReadWarnings, pluralSuffix(report.MetadataReadWarnings)))
355		}
356		if report.CheckpointsAnalyzed > 0 {
357			limitations = append(limitations, "Tool-level search/read spend is not captured yet; this profile infers patterns from token totals, cache/context replay, API call counts, and subagent totals.")
358		}
