391	func writeTokensProfileSignals(w io.Writer, signals []tokensProfileSignal) {
392		if len(signals) == 0 {
393			return
394		}
395	
396		fmt.Fprintln(w)
397		fmt.Fprintln(w, "Repeated signals")
398		for _, signal := range signals {
399			fmt.Fprintf(w, "- %s: %d checkpoint%s", signal.Label, signal.Count, pluralSuffix(signal.Count))
400			if signal.Percent > 0 {
401				fmt.Fprintf(w, " (%d%%)", signal.Percent)
402			}
403			fmt.Fprintln(w)
404		}
405	}
